function validate([edges, cost]) {
  const n = cost.length;
  if (n < 2 || n > 20000) return 'The tree needs 2 to 20000 nodes.';
  if (edges.length !== n - 1) return 'edges must have exactly n - 1 entries.';
  if (cost.some(c => !Number.isInteger(c) || c === 0 || Math.abs(c) > 10000)) return 'Each cost is a nonzero integer from -10^4 to 10^4.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge endpoints must be node numbers from 0 to n - 1.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'The edges must form a tree (no cycles).';
    root[ra] = rb;
  }
  return null;
}

