function placedCoins(edges, cost) {
  const n = cost.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }

  const parent = new Array(n).fill(-1);
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    for (const next of graph[node]) {
      if (next !== parent[node]) {
        parent[next] = node;
        order.push(next);
      }
    }
  }

  const size = new Array(n).fill(1);
  const extremes = cost.map((value) => [value]);
  const coin = new Array(n).fill(1);
  for (let i = n - 1; i >= 0; i--) {
    const node = order[i];
    const values = extremes[node].sort((a, b) => a - b);
    const m = values.length;
    if (size[node] >= 3) {
      const topThree = values[m - 1] * values[m - 2] * values[m - 3];
      const twoLowest = values[0] * values[1] * values[m - 1];
      coin[node] = Math.max(topThree, twoLowest, 0);
    }
    const kept = m > 5 ? [...values.slice(0, 2), ...values.slice(m - 3)] : values;
    if (node !== 0) {
      size[parent[node]] += size[node];
      extremes[parent[node]].push(...kept);
    }
  }
  return coin;
}

