function placedCoins(edges, cost) {
  const n = cost.length;
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  const up = new Array(n).fill(-1);
  const seen = new Array(n).fill(false);
  const stack = [0];
  seen[0] = true;
  while (stack.length) {
    const u = stack.pop();
    for (const v of adj[u]) if (!seen[v]) { seen[v] = true; up[v] = u; stack.push(v); }
  }
  // Every node's cost belongs to the subtree of each of its ancestors (and itself).
  const members = Array.from({ length: n }, () => []);
  for (let v = 0; v < n; v++) for (let a = v; a !== -1; a = up[a]) members[a].push(cost[v]);
  return members.map(list => {
    if (list.length < 3) return 1;
    let best = -Infinity;
    for (let i = 0; i < list.length; i++)
      for (let j = i + 1; j < list.length; j++)
        for (let k = j + 1; k < list.length; k++) best = Math.max(best, list[i] * list[j] * list[k]);
    return best < 0 ? 0 : best;
  });
}

