function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1800, 2000) : int(2, 9);
  const shape = int(0, 3);
  const links = [];
  for (let i = 1; i < n; i++) {
    // 0: random tree, 1: path, 2: star, 3: shallow bushy tree.
    const p = shape === 0 ? int(0, i - 1) : shape === 1 ? i - 1 : shape === 2 ? 0 : int(Math.max(0, i - 4), i - 1) >> 1;
    links.push([p, i]);
  }
  // Relabel the nodes so node 0 can sit anywhere in the shape.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = links.map(([a, b]) => rand() < 0.5 ? [label[a], label[b]] : [label[b], label[a]]);
  for (let i = edges.length - 1; i > 0; i--) { const j = int(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const span = size === 'large' || rand() < 0.3 ? 10000 : 10;
  const negativeShare = [0, 0.3, 0.5, 0.8, 1][int(0, 4)];
  const cost = Array.from({ length: n }, () => (rand() < negativeShare ? -1 : 1) * int(1, span));
  return [edges, cost];
}
